function DOMRegex(regex){let output=[];for(let i of document.querySelectorAll("*")){if(regex.test(i.id)){output.push(i)}}return output}function showMessage(msg_type,message){const Toast=Swal.mixin({toast:true,position:"bottom-end",showConfirmButton:false,timer:3e3,timerProgressBar:true,onOpen:toast=>{toast.addEventListener("mouseenter",Swal.stopTimer);toast.addEventListener("mouseleave",Swal.resumeTimer)}});Toast.fire({icon:msg_type,title:"&nbsp;&nbsp;"+message})}function getBootstrapBreakpoint(){var w=$(document).innerWidth();return w<576?"xs":w<768?"sm":w<992?"md":w<1200?"lg":"xlg"}function getColumnCount(){var breakpoint=getBootstrapBreakpoint();if(breakpoint==="xs"){return 1}else if(breakpoint==="sm"){return 2}else if(breakpoint==="md"){return 3}else if(breakpoint==="lg"){return 4}else{return 6}}function resizeEnd(){SetTabContentFilter()}